        {
            // Validate the input data
            if (data == null)
            {
                return BadRequest("Data cannot be null");
            }
            // Process the data
            var result = await _userService.ProcessUserDataAsync(data);
            // Return the processed result
            return Ok(result);
        }

        /**
         * Deletes a user by their unique identifier.
         */
