pub fn parse_ports(spec: &str) -> Result<Vec<u16>, String> {
    let mut out = Vec::new();
    for part in spec.split(',') {
        let part = part.trim();
        if part.is_empty() {
            continue;
        }
        match part.split_once('-') {
            Some((a, b)) => {
                let lo: u16 = a.parse().map_err(|_| format!("bad port {a}"))?;
                let hi: u16 = b.parse().map_err(|_| format!("bad port {b}"))?;
                out.extend(lo..=hi);
            }
            None => out.push(part.parse().map_err(|_| format!("bad port {part}"))?),
        }
    }
    Ok(out)
}
